INSERT INTO public.quiz_questions (group_id, language, category, question, options, correct_index, explanation, source, is_active, sort_order)
VALUES
('0d90fb7c-aa56-5ec0-bd46-102c08fe45bf'::uuid, 'az', 'pregnancy', 'Ev hamiləlik testi hansı hormonu ölçür?', '["hCG", "İnsulin", "Melatonin", "Adrenalin"]'::jsonb, 0, 'Bu hormon döl yumurtası uşaqlığa yerləşəndən sonra artır. Aybaşı gecikəndən sonra test daha dəqiq olur.', 'ACOG', true, 201),
('c2c8d2c9-6d62-521b-a4dc-35d87bcdc1bd'::uuid, 'az', 'pregnancy', 'Doğuş tarixini ən dəqiq hansı müayinə müəyyən edir?', '["İlk trimestrdə ultrasəs", "Son trimestrdə ultrasəs", "Ananın çəkisi", "Qarının ölçüsü"]'::jsonb, 0, 'Erkən dövrdə körpələrin ölçüsü bir-birinə çox yaxın olduğu üçün bu ölçü ən dəqiqdir.', 'ACOG', true, 202),
('e150ff07-efcf-5a5a-a777-cdd1e06b7495'::uuid, 'az', 'pregnancy', 'Hamiləlikdə körpənin beyin və qalxanabənzər vəzi inkişafı üçün hansı mineral vacibdir?', '["Qurğuşun", "Yod", "Civə", "Alüminium"]'::jsonb, 1, 'Yodlaşdırılmış duz və vitamin kompleksləri yodun əsas mənbəyidir.', 'ÜST', true, 203),
('a7670665-5587-5366-aa9e-09997a66fae3'::uuid, 'az', 'pregnancy', 'Hamiləlikdə gündə təxminən nə qədər kalsium lazımdır?', '["Kalsium lazım deyil", "5000 mq", "1000 mq", "50 mq"]'::jsonb, 2, 'Süd məhsulları, kunjut, yaşıl yarpaqlı tərəvəzlər yaxşı mənbədir.', 'ACOG', true, 204),
('390b98a0-7fa1-599a-9d5c-d05642ad7705'::uuid, 'az', 'pregnancy', 'Hamiləlikdə qaraciyər və yüksək dozalı A vitamini əlavələrindən niyə çəkinilir?', '["Çox kalorilidir", "Körpədə inkişaf qüsuru riski var", "Ürək yanması verir", "Yuxusuzluq yaradır"]'::jsonb, 1, 'Tərəvəzdəki beta-karotin isə təhlükəsizdir.', 'NHS', true, 205),
('0cb5a766-cba2-504f-85c4-d187bf8c82ef'::uuid, 'az', 'pregnancy', 'Hamiləlikdə bel ağrısını nə azalda bilər?', '["Hündür daban", "Bütün gün uzanmaq", "Ağır əşya qaldırmaq", "Düz duruş, alçaq daban, dizlər arasında yastıqla yatmaq"]'::jsonb, 3, 'Ağrı çox güclüdürsə və ya qanaxma varsa, həkimə müraciət et.', 'NHS', true, 206),
('1528e9dd-a66f-5641-8c1d-c4ea3ecd56c9'::uuid, 'az', 'pregnancy', 'Hamiləlikdə gecə ayaq qıclanması (kramp) zamanı nə kömək edir?', '["Ayağı bərk sıxmaq", "Baldırı dartıb masaj etmək", "Soyuq suya salmaq", "Heç bir şey"]'::jsonb, 1, 'Gün ərzində hərəkət və yatmazdan əvvəl yüngül dartınma qıclanmaları azaldır.', 'NHS', true, 207),
('84af12a2-22fd-5eee-a23c-b389832caa4a'::uuid, 'az', 'pregnancy', 'Hamiləlikdə ayaq şişkinliyini nə azaldır?', '["Dar corab və ayaqqabı", "Duzlu qida çoxaltmaq", "Suyu tamamilə kəsmək", "Ayaqları qaldırıb dincəlmək, uzun müddət ayaqda durmamaq"]'::jsonb, 3, 'Üzdə və əllərdə qəfil şişkinlik isə həkimə müraciət tələb edir.', 'NHS', true, 208),
('6265f4d3-7d46-5cec-b4dc-e1806c99bc51'::uuid, 'az', 'pregnancy', 'Hamiləlikdə istənilən vaginal qanaxma zamanı nə etmək lazımdır?', '["İdmanı artırmaq", "Həkimə xəbər vermək", "Bir həftə gözləmək", "Normal saymaq"]'::jsonb, 1, 'Az qanaxma da yoxlanmalıdır. Güclü qanaxma və ağrı olarsa, təcili yardım çağır.', 'ACOG', true, 209),
('326bd452-98e7-55a8-8984-357beaf4fa4c'::uuid, 'az', 'pregnancy', 'Erkən hamiləlikdə bir tərəfli kəskin qarın ağrısı və qanaxma nəyin əlaməti ola bilər?', '["Qəbizlik", "Uşaqlıqdankənar hamiləlik", "Ürək yanması", "Normal hamiləlik"]'::jsonb, 1, 'Bu təcili vəziyyətdir. Dərhal həkimə müraciət et.', 'ACOG', true, 210),
('1667986b-531a-53fd-b967-7c7fd6a5ea5c'::uuid, 'az', 'pregnancy', 'Doğuş planı nədir?', '["Doğuşla bağlı arzuların yazılı siyahısı", "Həkimin doğuş günü təyini", "Körpənin yuxu cədvəli", "Xəstəxana ödəniş planı"]'::jsonb, 0, 'Ağrı kəsmə, yanında kimin olacağı kimi istəkləri həkimlə əvvəlcədən müzakirə et. Plan dəyişə bilər.', 'NHS', true, 211),
('77dfd7a9-0add-54e9-b1f6-3af2b61cb870'::uuid, 'az', 'pregnancy', 'Epidural nədir?', '["Ümumi narkoz", "Doğuşu sürətləndirən dərman", "Qeysəriyyə əməliyyatı", "Doğuş ağrısını azaldan regional anesteziya"]'::jsonb, 3, 'Ana oyaq qalır, bədənin aşağı hissəsində ağrı azalır.', 'ACOG', true, 212),
('6c49bb3a-b5ed-5bf4-900d-579680f3a28c'::uuid, 'az', 'pregnancy', 'Hamiləlikdə hansı qan təzyiqi yüksək sayılır?', '["100/60", "110/70", "120/80", "140/90 və yuxarı"]'::jsonb, 3, 'Evdə təzyiq ölçürsənsə, yüksək rəqəmləri həkimə bildir.', 'ACOG', true, 213),
('b915ff35-cdc2-5df9-abfb-59ec03b68615'::uuid, 'az', 'pregnancy', 'Doğum evi çantasını nə vaxta qədər hazırlamaq tövsiyə olunur?', '["12-ci həftədə", "Təxminən 36-cı həftəyə qədər", "Doğuşdan sonra", "Doğuş günü"]'::jsonb, 1, 'Anacan-dakı "Xəstəxana çantası" siyahısı bu işdə kömək edir.', 'NHS', true, 214),
('205bb8b9-497f-5791-9b3f-65e9e72b2001'::uuid, 'az', 'pregnancy', 'Hamiləlikdə sidik ifrazı zamanı yanma hiss olunursa, nə etmək lazımdır?', '["Gözləmək", "Normal saymaq", "Həkimə müraciət etmək", "Su içməyi azaltmaq"]'::jsonb, 2, 'Hamiləlikdə sidik yolu infeksiyası müalicə olunmalıdır, yoxsa böyrəyə keçə bilər.', 'ACOG', true, 215),
('e85ebf52-d677-5a0d-852b-3bcb6ba3a21c'::uuid, 'az', 'pregnancy', 'Hamiləlikdə üzdə əmələ gələn tünd ləkələrin (melazma) qarşısını nə alır?', '["Günəşlənmək", "Günəşdən qorunmaq", "Ləkəni ovmaq", "Ağardıcı kremlər"]'::jsonb, 1, 'Ləkələr çox vaxt doğuşdan sonra solğunlaşır.', 'AAD', true, 216),
('7f34151c-f5ef-58c7-a012-d26591f18be7'::uuid, 'az', 'pregnancy', 'Əkiz hamiləlikdə doğuş adətən nə vaxt olur?', '["Həmişə 42-ci həftədə", "Yalnız 30-cu həftədə", "Təkdən daha gec", "Təkdən daha tez, təxminən 36-37-ci həftədə"]'::jsonb, 3, 'Əkiz hamiləlikdə müayinələr daha tez-tez aparılır.', 'ACOG', true, 217),
('17734e26-751d-52d4-be00-a9df65647a73'::uuid, 'az', 'pregnancy', 'Hamiləlikdə saç boyası haqqında hansı fikir doğrudur?', '["Körpəyə mütləq zərər verir", "Riski azdır, ilk trimestrdən sonra, havası dəyişən yerdə daha yaxşıdır", "Yalnız ilk trimestrdə olar", "Tamamilə qadağandır"]'::jsonb, 1, 'Əlcək tax və təlimatdakı müddətdən artıq saxlama.', 'NHS', true, 218),
('942d56fa-bceb-55b5-b1e5-e47bb186a92e'::uuid, 'az', 'baby_food', 'Bir əmizdirmədə döşün sona qədər boşalması niyə faydalıdır?', '["Südün sonu daha yağlı və doyurucudur", "Heç bir faydası yoxdur", "Südün sonu sudur", "Döş daha az süd verir"]'::jsonb, 0, 'Körpəni ikinci döşə keçirməzdən əvvəl birincini yaxşı boşaltmasına imkan ver.', 'NHS', true, 219),
('36dc628d-88a7-5081-9aad-931f6d89cefa'::uuid, 'az', 'baby_food', 'Körpəni qidalandırarkən nə vaxt gəyirtmək lazımdır?', '["Yalnız gecə", "Heç vaxt", "Yalnız gündə bir dəfə", "Qidalanma arasında və sonunda"]'::jsonb, 3, 'Dik tutub kürəyinə yüngülcə vur və ya sığalla.', 'AAP', true, 220),
('5f9adce3-dc77-580d-924d-32ad0a72739f'::uuid, 'az', 'baby_food', 'Körpənin yeməkdən sonra az miqdarda süd qaytarması haqqında hansı fikir doğrudur?', '["Çəki artırsa, çox vaxt normaldır və 1 yaşa keçir", "Qidalanmanı dayandırmaq lazımdır", "Süd qarışığını dəyişmək mütləqdir", "Həmişə ciddi xəstəlikdir"]'::jsonb, 0, 'Körpə narahatdırsa, çəki almırsa və ya qusma güclüdürsə, həkimə müraciət et.', 'AAP', true, 221),
('7bc49668-26d8-536d-9ebb-968471207537'::uuid, 'az', 'baby_food', 'Körpəni şüşə ilə qidalandırarkən necə tutmaq lazımdır?', '["Tək qoyub şüşəni ağzında saxlamaq", "Yarımdik, qucaqda, şüşəni dayağa söykəmədən", "Qarnı üstə", "Arxası üstə uzadıb şüşəni yastığa söykəmək"]'::jsonb, 1, 'Dayaqla qidalandırma boğulma və qulaq iltihabı riskini artırır.', 'AAP', true, 222),
('6628e9ea-6884-5a52-93ce-84b7a87fa4e7'::uuid, 'az', 'baby_food', 'Əlavə qidada tekstura necə dəyişməlidir?', '["Yalnız maye", "Bir yaşa qədər yalnız hamar püre", "Birbaşa böyüklərin bərk yeməyi", "Hamar püredən tədricən dənəli və barmaq qidalarına"]'::jsonb, 3, 'Uzun müddət yalnız püre vermək sonradan çeynəməyi öyrənməyi çətinləşdirə bilər.', 'NHS', true, 223),
('fab28f0d-55f6-5ac1-ace6-72e4dcd9c731'::uuid, 'az', 'baby_food', '1-2 yaşlı uşağa hansı süd tövsiyə olunur?', '["Qatılaşdırılmış şirin süd", "Şokoladlı süd", "Tam yağlı süd", "Yağsız süd"]'::jsonb, 2, 'Bu yaşda beyin inkişafı üçün yağ lazımdır. 2 yaşdan sonra az yağlı südə keçmək olar.', 'AAP', true, 224),
('7cd910ba-0a90-59ca-9c3a-b3cdb9c63fe8'::uuid, 'az', 'baby_food', '1 yaşdan sonra uşaq gündə nə qədər süd içməlidir?', '["Yalnız gecə 1 litr", "Təxminən 2-3 stəkan (500 ml-ə qədər)", "2 litrdən çox", "Heç içməməli"]'::jsonb, 1, 'Çox süd iştahanı azaldır və dəmir çatışmazlığına səbəb ola bilər.', 'AAP', true, 225),
('aefad558-3213-5636-ac6c-f14378a9334c'::uuid, 'az', 'baby_food', 'Yemək zamanı kim nəyə qərar verir?', '["Heç kim", "Valideyn uşağın nə qədər yeyəcəyini", "Valideyn nəyi və nə vaxt, uşaq nə qədər yeyəcəyini", "Uşaq hər şeyi"]'::jsonb, 2, 'Uşağı yeməyə məcbur etmək iştahanı və yeməklə münasibəti pozur.', 'AAP', true, 226),
('b8b3cc66-1224-5d72-9cef-30e768cdf42f'::uuid, 'az', 'baby_food', 'Yemək zamanı uşağa televizor və ya telefon göstərmək haqqında hansı fikir doğrudur?', '["Tövsiyə olunmur, toxluğu hiss etməyə mane olur", "Yalnız səhər olar", "İştahanı yaxşılaşdırır", "Mütləq lazımdır"]'::jsonb, 0, 'Ailəcə masa arxasında söhbət edərək yemək ən yaxşı vərdişdir.', 'AAP', true, 227),
('b8747b78-d6c1-5e79-af65-cde5a0d124fa'::uuid, 'az', 'baby_food', 'Əmizdirən ananın yediyi qidalar haqqında hansı fikir doğrudur?', '["Yalnız düyü yemək lazımdır", "Südə heç təsir etmir", "Ədviyyat tamamilə qadağandır", "Südün dadını dəyişir və körpəni yeni dadlara alışdırır"]'::jsonb, 3, 'Müxtəlif qidalanma faydalıdır. Körpədə müəyyən qidadan sonra reaksiya görürsənsə, həkimlə danış.', 'AAP', true, 228),
('77769ec5-f001-5542-a1db-b05e8ee56ade'::uuid, 'az', 'baby_food', 'Badam və ya düyü südü 1 yaşa qədər nəyi əvəz edə bilərmi?', '["Yalnız gecə əvəz edir", "Xeyr, ana südünü və süd qarışığını əvəz etmir", "Bəli, daha faydalıdır", "Bəli, tam əvəz edir"]'::jsonb, 1, 'Bu içkilərdə körpə üçün lazım olan protein və yağ azdır.', 'AAP', true, 229),
('667932ba-3b9f-5e5c-8beb-525508fbf30d'::uuid, 'az', 'baby_food', 'Açılmış körpə püresi bankasını necə saxlamaq lazımdır?', '["Dondurucuda bir il", "Soyuducuda 1-2 gün, qaşığı bankaya salmadan", "Qaşıqla bankadan yedirib saxlamaq", "Otaqda bir həftə"]'::jsonb, 1, 'Yedirəcəyin hissəni ayrıca qaba çıxar, tüpürcək bakteriyaları qalanını xarab edir.', 'USDA', true, 230),
('d9f91c2b-2a71-5c29-a07e-35a2d8ba3abe'::uuid, 'az', 'baby_food', 'Körpə qidasında yağın rolu haqqında hansı fikir doğrudur?', '["Yalnız marqarin lazımdır", "Yağ tamamilə çıxarılmalıdır", "Yağ yalnız 5 yaşdan sonra", "Sağlam yağlar beyin inkişafı üçün vacibdir"]'::jsonb, 3, 'Avokado, zeytun yağı, balıq yaxşı mənbədir.', 'AAP', true, 231),
('763a6ac5-2c1e-529f-9fee-b1b57d418857'::uuid, 'az', 'baby_food', 'Mikrodalğalı sobada qızdırılmış qidanı uşağa verməzdən əvvəl nə etmək lazımdır?', '["Yaxşıca qarışdırıb temperaturunu yoxlamaq", "Dərhal vermək", "Yalnız üstündən dadmaq", "Üfürmək kifayətdir"]'::jsonb, 0, 'Mikrodalğa qidada çox isti nöqtələr yaradır.', 'NHS', true, 232),
('895969ed-6844-5802-b1e4-1a8791f6b6b5'::uuid, 'az', 'baby_food', 'Körpənin ilk ət yeməyi necə hazırlanmalıdır?', '["Tam bişmiş, yumşaq, xırda doğranmış və ya püre", "Çiy", "Az bişmiş, qanlı", "Qızardılmış bərk tikələr"]'::jsonb, 0, 'Ət dəmir və sinkin yaxşı mənbəyidir.', 'NHS', true, 233),
('71b04a51-9e27-5152-a8e7-1782bc633286'::uuid, 'az', 'baby_food', 'Əlavə qida yaşında uşağa hansı içki ən yaxşısıdır?', '["Şirin kompot", "Enerji içkisi", "Su və süd", "Qazlı içki"]'::jsonb, 2, 'Şirin içkilər diş çürüməsinə və iştahanın azalmasına səbəb olur.', 'AAP', true, 234),
('0c4c767e-37b8-5c3f-8910-bcf65d071ba5'::uuid, 'az', 'sleep', 'Yuxuda körpənin hırıldaması, qımıldanması və səs çıxarması haqqında hansı fikir doğrudur?', '["Mütləq xəstəlikdir", "Körpə ac qalıb", "Dərhal oyatmaq lazımdır", "Çox vaxt normaldır, hər səsdə oyatmaq lazım deyil"]'::jsonb, 3, 'Körpələrin yuxusunun çox hissəsi aktiv yuxudur. Nəfəs çətinliyi varsa, həkimə müraciət et.', 'AAP', true, 235),
('d598f3f5-a74a-5ce2-806a-af76404d660e'::uuid, 'az', 'sleep', '6-12 aylıq körpə adətən gündə neçə dəfə gündüz yuxusu yatır?', '["2 dəfə", "10 dəfə", "6 dəfə", "Heç yatmır"]'::jsonb, 0, 'Bəzi körpələr 12-18 ay arası bir gündüz yuxusuna keçir.', 'AAP', true, 236),
('fae91df5-aef8-5ff7-bd3e-04d9d1c52855'::uuid, 'az', 'sleep', 'Beşiyin barmaqlıqları arasındakı məsafə nə qədər olmalıdır?', '["Fərqi yoxdur", "15 sm", "20 sm", "6 sm-dən çox olmamalıdır"]'::jsonb, 3, 'Daha geniş aralıqda körpənin başı ilişə bilər.', 'CPSC', true, 237),
('9fca8227-6c34-529e-9729-93a29cd823a4'::uuid, 'az', 'sleep', 'Uşağı beşikdən çarpayıya nə vaxt keçirmək lazımdır?', '["3 aylıqda", "Doğuşdan", "Heç vaxt", "Beşikdən çıxmağa cəhd edəndə"]'::jsonb, 3, 'Çıxmağa çalışan uşaq beşikdən yıxıla bilər.', 'AAP', true, 238),
('561af5f6-a89b-52b2-9884-9fff7717e881'::uuid, 'az', 'sleep', 'Həftə sonları uşağın yuxu saatı necə olmalıdır?', '["Tamamilə sərbəst", "Mümkün qədər iş günləri ilə eyni", "Gündüz yatmalı, gecə oyaq qalmalı", "Çox gec yatmalı"]'::jsonb, 1, 'Sabit qrafik bioloji saatı qoruyur.', 'AAP', true, 239),
('4895e96a-a114-5b8e-99e6-d2b80d1a3b76'::uuid, 'az', 'sleep', 'Kabus görüb oyanan uşaqla nə etmək lazımdır?', '["Danlamaq", "Qorxulu film göstərmək", "Sakitləşdirmək, yanında olmaq", "Tək buraxmaq"]'::jsonb, 2, 'Kabusdan sonra uşaq oyaq olur və təsəlliyə ehtiyac duyur.', 'AAP', true, 240),
('69e5e611-62fd-533c-95a3-3701813fb282'::uuid, 'az', 'sleep', 'Uşaqların yuxuda dişlərini qıcırtması haqqında hansı fikir doğrudur?', '["Yalnız böyüklərdə olur", "Dişləri dərhal çəkmək lazımdır", "Həmişə ciddi xəstəlikdir", "Tez-tez olur və çox vaxt özü keçir"]'::jsonb, 3, 'Dişlərdə aşınma və ya ağrı görsən, diş həkiminə göstər.', 'AAPD', true, 241),
('6f1272ec-4f8d-5960-a387-43c437b5cd13'::uuid, 'az', 'sleep', 'Gecə yatağı islatmaq neçə yaşa qədər normal sayılır?', '["Təxminən 5 yaşa qədər", "Heç vaxt normal deyil", "2 yaşa qədər", "1 yaşa qədər"]'::jsonb, 0, 'Uşağı cəzalandırma. Bu, iradə yox, inkişafla bağlıdır.', 'AAP', true, 242),
('471b55bf-b010-5bf7-ab9f-20ea9b9f0da0'::uuid, 'az', 'sleep', 'Kola kimi kofeinli içkilər uşağın yuxusuna necə təsir edir?', '["Yuxunu pozur", "Yuxunu yaxşılaşdırır", "Heç təsir etmir", "Yalnız səhər təsir edir"]'::jsonb, 0, 'Uşaqlar üçün kofeinli içkilər tövsiyə olunmur.', 'AAP', true, 243),
('5fd6eac0-840c-5fca-ba86-81db00782459'::uuid, 'az', 'sleep', 'Qucaqda yatmış körpəni beşiyə nə vaxt köçürmək daha asandır?', '["Ağlayarkən", "Dərin yuxuya keçəndən sonra, təxminən 10-20 dəqiqə", "Gözünü yumduğu an", "Yalnız səhər"]'::jsonb, 1, 'Dərin yuxuda qolları boşalır, nəfəsi yavaşıyır.', 'AAP', true, 244),
