('06e44c0a-41be-5f8a-a3a6-24eea88e35ef'::uuid, 'az', 'development', 'Körpə "ba-ba-ba" kimi hecalar deməyə adətən nə vaxt başlayır?', '["1 aylıqda", "2 yaşda", "2 aylıqda", "6-9 aylıqda"]'::jsonb, 3, 'Bu səslər hələ məna daşımasa da nitqin vacib mərhələsidir.', 'CDC', true, 249),
('a0f95760-769f-5105-9b30-c13b3a5f7ba4'::uuid, 'az', 'development', 'Yeni doğulmuşdakı diksinmə (Moro) refleksi adətən nə vaxt itir?', '["3 yaşda", "1 həftəlikdə", "Heç itmir", "4-6 aylıqda"]'::jsonb, 3, 'Bu refleks sağlam sinir sisteminin əlamətidir.', 'AAP', true, 250),
('b861283a-e30f-5f9c-8d6d-0d5e7ecd344b'::uuid, 'az', 'development', 'Uşaq adətən nə vaxt qaçmağa başlayır?', '["6 aylıqda", "5 yaşda", "Təxminən 2 yaşda", "9 aylıqda"]'::jsonb, 2, 'Açıq havada oyun hərəkət bacarıqlarını gücləndirir.', 'CDC', true, 251),
('edbc075a-f7fe-585f-ac23-3edd061628f7'::uuid, 'az', 'development', 'Uşaq üçtəkərli velosiped sürməyi adətən nə vaxt bacarır?', '["6 aylıqda", "7 yaşda", "Təxminən 3 yaşda", "1 yaşda"]'::jsonb, 2, 'Dəbilqə taxmağı da elə ilk gündən vərdiş et.', 'CDC', true, 252),
('80832e6d-e896-551a-9daa-f9ff6d40c9ef'::uuid, 'az', 'development', 'Uşaq dairə çəkməyi adətən nə vaxt bacarır?', '["6 aylıqda", "6 yaşda", "Təxminən 3 yaşda", "1 yaşda"]'::jsonb, 2, 'Rəsm çəkmək həm əl bacarığını, həm də təxəyyülü inkişaf etdirir.', 'CDC', true, 253),
('fb325423-cba6-5352-89bb-69bd47878521'::uuid, 'az', 'development', 'Uşaq rəngləri adlandırmağı adətən nə vaxt öyrənir?', '["3-4 yaşda", "1 yaşda", "7 yaşda", "6 aylıqda"]'::jsonb, 0, 'Gündəlik danışıqda rəngləri adlandır: "qırmızı alma", "sarı top".', 'CDC', true, 254),
('63663d3e-709f-5015-8f3a-c6bc78b21708'::uuid, 'az', 'development', '"Elə bil" oyunu (kuklanı yedirtmək, telefonla danışmaq) adətən nə vaxt başlayır?', '["5 yaşda", "18 ay ilə 2 yaş arası", "2 aylıqda", "6 aylıqda"]'::jsonb, 1, 'Bu oyunlar dil və sosial bacarıqları inkişaf etdirir.', 'CDC', true, 255),
('43a11fc5-d82a-5e36-bbfb-8993e8d372b7'::uuid, 'az', 'development', 'Uşaq oyuncaqlarını başqaları ilə paylaşmağı adətən nə vaxt öyrənir?', '["Təxminən 3 yaşda", "6 aylıqda", "1 yaşda", "10 yaşda"]'::jsonb, 0, 'Bundan əvvəl paylaşmamaq normaldır. Növbə ilə oynamağı oyunla öyrət.', 'AAP', true, 256),
('cf561837-6981-54f8-85f5-6c2a94380912'::uuid, 'az', 'development', '2-5 yaşda kəkələmə haqqında hansı fikir doğrudur?', '["Tez-tez olur və çox vaxt keçicidir", "Uşağı tez danışmağa məcbur etmək lazımdır", "Həmişə ömürlük qalır", "Pis tərbiyənin nəticəsidir"]'::jsonb, 0, 'Səbirlə dinlə, sözünü tamamlama. 6 aydan çox davam edərsə, loqopedlə danış.', 'ASHA', true, 257),
('66eebae8-4b41-5c17-9bcd-0ce2b49d881e'::uuid, 'az', 'development', 'Uşaq sol əli ilə yazırsa, nə etmək lazımdır?', '["Normaldır, dəyişdirməyə məcbur etmək lazım deyil", "Sol əlini bağlamaq", "Həkimə aparmaq lazımdır", "Sağ ələ öyrətmək mütləqdir"]'::jsonb, 0, 'Əl seçimi adətən 4-6 yaşda tam formalaşır.', 'AAP', true, 258),
('b2a477ad-3186-56cb-9ec1-ec83954862b6'::uuid, 'az', 'development', 'Uşaq barmağını əmirsə, nə vaxt diş həkiminə göstərmək lazımdır?', '["4 yaşdan sonra davam edərsə", "Heç vaxt", "6 aylıqda", "1 aylıqda"]'::jsonb, 0, 'Çox uşaq bu vərdişi özü buraxır. Danlamaq əvəzinə tərif və diqqəti yayındırmaq kömək edir.', 'AAPD', true, 259),
('17444e81-ee1f-5f12-b062-db011b6d33f2'::uuid, 'az', 'development', 'Yeni doğulmuşun eşitməsi nə vaxt yoxlanmalıdır?', '["Danışmasa", "Məktəbdə", "Doğum evində və ya ilk ayda", "3 yaşda"]'::jsonb, 2, 'Erkən aşkar olunan eşitmə problemi erkən müalicə deməkdir.', 'AAP', true, 260),
('f940aed2-9276-5266-b0ab-5e66bff6401f'::uuid, 'az', 'health', 'Gözdən irinli axıntı və göz qapaqlarının yapışması nəyin əlaməti ola bilər?', '["Göz infeksiyasının (konyunktivit)", "Normal yorğunluğun", "Diş çıxarmanın", "Boy artımının"]'::jsonb, 0, 'Gözü təmiz, qaynadılıb soyudulmuş su ilə sil və həkimə göstər.', 'AAP', true, 261),
